const isHalfReimbursed = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;

const damagedItem = (insuredItems: Item[], damage: Damage): Item | undefined =>
  insuredItems.find((item) => item.type === damage.itemType);

// A reimbursement clause pays a percentage of the damage other than the default
// 100 %. Clauses are listed in precedence order and the first applicable one
// wins — the dragon-material clause will slot in below the enchantment one.
type ReimbursementClause = {
  applies: (item: Item) => boolean;
  percent: number;
};

const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
  { applies: isHalfReimbursed, percent: HALF_REIMBURSEMENT_PERCENT },
];

const FULL_REIMBURSEMENT_PERCENT = 100;

// No insured item means no clause applies. That an unmatched damage reimburses
// in full is not a rule of the domain, only the current default: the pending
// "item not part of the policy" test will reject such a claim outright.
const reimbursementPercent = (item: Item | undefined): number =>
  REIMBURSEMENT_CLAUSES.find((clause) => item !== undefined && clause.applies(item))
    ?.percent ?? FULL_REIMBURSEMENT_PERCENT;

// What a damage entry reimburses before the deductible: a percentage of the
// damage amount, decided by the clauses covering the damaged item.
const reimbursableAmount = (insuredItems: Item[], damage: Damage): number =>
  percentOf(
    damage.amount,
    reimbursementPercent(damagedItem(insuredItems, damage)),
  );

